   99	    /**
  100	     * The gap between one planet's order and the next in a login, the way a player clicks through
  101	     * planets. It also keeps a session's intents from reaching the workers in the same instant, where
  102	     * all but one lose the per-player lock and wait out a retry.
  103	     */
  104	    private const SECONDS_BETWEEN_PLANETS = 20;
