  122	    /**
  123	     * Writes the one work item that carries the intent out, keyed by the session's
  124	     * own id: a retried session converges on one action, a later session decides
  125	     * again. The payload is whatever the plan approved, so the schedule and the
  126	     * executor always name the same objective.
  127	     *
  128	     * @param array<string, mixed> $payload
  129	     */
  130	    private function enqueue(AiProfile $profile, AiWorkItem $sessionWorkItem, AiWorkKind $kind, array $payload, ?CarbonImmutable $dueAt = null, string $keySuffix = ''): void
  131	    {
  132	        AiWorkItem::query()->firstOrCreate(
  133	            ['idempotency_key' => 'intent:session:' . $sessionWorkItem->id . $keySuffix],
  134	            [
  135	                'player_id' => $profile->player_id,
  136	                'kind' => $kind,
  137	                'due_at' => $dueAt ?? $this->clock->now(),
  138	                'schedule_generation' => (int) ($sessionWorkItem->schedule_generation ?? 1),
  139	                'state' => AiWorkState::Pending,
  140	                'payload' => $payload,
  141	            ],
  142	        );
  143	    }
