  145	    public function handle(AiProfile $profile, AiWorkItem $sessionWorkItem, DecisionTrace $trace): void
  146	    {
  147	        // Every case is listed: adding a capability means deciding here where it is executed, and
  148	        // a capability with no executor must not be published to begin with.
  149	        $type = $trace->selected->candidate->type;
  150	        // A player refills the build queues and the lab every login before turning to the shipyard or
  151	        // the fleet; choosing a raid or a ship must not leave nine planets idle until the next session.
  152	        // A transfer or a save is priced against the very balance a queue would spend, and a session
  153	        // that placed no order has nothing to spend on: neither may refill the queues.
  154	        $economySteps = $this->fillsEconomy($type) && !in_array($type, [AiCandidateActionType::Transfer, AiCandidateActionType::FleetSave, AiCandidateActionType::DoNothing], true) && $this->economyOffered($trace)
  155	            ? $this->fillQueues($profile, $sessionWorkItem, ':economy')
  156	            : 0;
  157	
  158	        match ($type) {
  159	            AiCandidateActionType::Build, AiCandidateActionType::Research => $this->fillQueues($profile, $sessionWorkItem, ''),
  160	            // The shipyard gets what the buildings leave, so its order waits until they are placed:
  161	            // the host cancels a building it cannot pay for, and a ship order placed first would cause it.
  162	            AiCandidateActionType::QueueUnits => $this->scheduleUnits($profile, $sessionWorkItem, $this->clock->now()->addSeconds($economySteps * self::SECONDS_BETWEEN_PLANETS)),
  163	            AiCandidateActionType::Colonize => $this->scheduleColony($profile, $sessionWorkItem),
  164	            AiCandidateActionType::Expedition => $this->scheduleExpedition($profile, $sessionWorkItem),
  165	            AiCandidateActionType::Transfer => $this->scheduleTransfer($profile, $sessionWorkItem),
  166	            AiCandidateActionType::Recycle => $this->scheduleRecycle($profile, $sessionWorkItem),
  167	            AiCandidateActionType::FleetSave => $this->scheduleFleetSave($profile, $sessionWorkItem),
  168	            AiCandidateActionType::Recall => $this->scheduleRecall($profile, $sessionWorkItem),
  169	            AiCandidateActionType::Spy => $this->scheduleSpy($profile, $sessionWorkItem),
  170	            AiCandidateActionType::Raid => $this->scheduleRaid($profile, $sessionWorkItem, $trace),
  171	            AiCandidateActionType::ThrottleMine => $this->scheduleMinePercent($profile, $sessionWorkItem),
  172	            AiCandidateActionType::Phalanx => $this->schedulePhalanx($profile, $sessionWorkItem),
  173	            AiCandidateActionType::DoNothing => $this->recordQuietDecision($profile, $trace),
  174	        };
  175	    }
