  177	    /**
  178	     * Whether the economy is filled before the selected action. Transfers and saves move the stock
  179	     * away, so a building priced against it would be cancelled; Build and Research fill it themselves;
  180	     * an idle session is a player who did not log in to play.
  181	     */
  182	    private function fillsEconomy(AiCandidateActionType $type): bool
  183	    {
  184	        return match ($type) {
  185	            AiCandidateActionType::QueueUnits,
  186	            AiCandidateActionType::Spy,
  187	            AiCandidateActionType::Raid,
  188	            AiCandidateActionType::Expedition,
  189	            AiCandidateActionType::Recycle,
  190	            AiCandidateActionType::Recall,
  191	            AiCandidateActionType::Phalanx,
  192	            AiCandidateActionType::ThrottleMine,
  193	            AiCandidateActionType::Colonize => true,
  194	            default => false,
  195	        };
  196	    }
