  198	    /** Only what the engine offered this session, so legality and persona policy stay its own. */
  199	    private function economyOffered(DecisionTrace $trace): bool
  200	    {
  201	        foreach ($trace->candidates as $scored) {
  202	            if (in_array($scored->candidate->type, [AiCandidateActionType::Build, AiCandidateActionType::Research], true)) {
  203	                return true;
  204	            }
  205	        }
  206	
  207	        return false;
  208	    }
