   68	    public function steps(int $playerId, ?PlayerService $player = null, int $limit = PHP_INT_MAX): array
   69	    {
   70	        // An account the module does not manage has no policy to apply, so it gets no capability.
   71	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
   72	        if ($profile === null) {
   73	            return [];
   74	        }
   75	
   76	        // The module owns profile rows; the host owns accounts. A profile can outlive its account or
   77	        // be written by a fixture, and loading an account the host does not have throws -- so the
   78	        // precondition is asked here rather than discovered in the host service.
   79	        if (!User::query()->whereKey($playerId)->exists()) {
   80	            return [];
   81	        }
