   83	        // Refresh every planet's live balance once: the candidate pass reads stored amounts and
   84	        // energy, and a balance read stale is exactly the balance the queue later cancels on. The
   85	        // refresh stays in memory -- the observation path must not write.
   86	        $planets = ($player ?? $this->playerServiceFactory->make($playerId, true))->planets->all();
   87	        foreach ($planets as $planet) {
   88	            $planet->updateResources(false);
   89	            $planet->updateResourceProductionStats(false);
   90	            $planet->updateResourceStorageStats(false);
   91	        }
