 36	    /** @return array<int, ScoredCandidate> */
 37	    public function score(AiProfile $profile, CandidateGeneration $generation, string $decisionKey): array
 38	    {
 39	        $policy = $this->policyRegistry->for($profile->archetype);
 40	        $affectWeight = (float) app(AiRuntimeSettings::class)->affectDecisionWeight();
 41	        // One mood read per decision, never per candidate, and only when the opt-in weight is
 42	        // on: the default path performs no affect query and changes no score.
 43	        $appetite = $affectWeight > 0.0 ? $this->threatAppetite($profile) : 0.0;
 44	        $scored = [];
 45	        foreach ($generation->candidates as $candidate) {
 46	            if (!$policy->allows($candidate->type)) {
 47	                continue;
 48	            }
 49	
 50	            $features = $candidate->features;
 51	            $variation = ($this->randomSource->unitInterval($profile->random_seed, $decisionKey . ':' . $candidate->type->value) - 0.5) * $profile->skill_band->variationWeight();
 52	            $components = [
 53	                'resource_need' => $features['resource_need'] * self::RESOURCE_NEED_WEIGHT,
 54	                'safety' => $features['safety'] * self::SAFETY_WEIGHT,
 55	                'target_confidence' => $features['target_confidence'] * self::TARGET_CONFIDENCE_WEIGHT,
 56	                'travel_cost' => -$features['travel_cost'] * self::TRAVEL_COST_WEIGHT,
 57	                'recovery' => $features['recovery'] * self::RECOVERY_WEIGHT,
 58	                'archetype_preference' => $policy->preference($candidate->type) * self::ARCHETYPE_WEIGHT,
 59	                'seeded_variation' => $variation,
 60	                'affect' => $appetite * $this->appetiteDirection($candidate->type) * $affectWeight,
 61	            ];
 62	            $scored[] = app()->makeWith(ScoredCandidate::class, [
 63	                'candidate' => $candidate,
 64	                'score' => array_sum($components),
 65	                'components' => $components,
 66	            ]);
 67	        }
 68	
 69	        // A stable secondary key prevents an otherwise identical replay from
 70	        // changing only because PHP received candidates in a different order.
 71	        usort($scored, static fn (ScoredCandidate $left, ScoredCandidate $right): int => $right->score <=> $left->score ?: $left->candidate->type->value <=> $right->candidate->type->value);
 72	
 73	        return $scored;
 74	    }
