 90	    /**
 91	     * Which way a candidate type leans on the appetite: an attack wants anger, a save or
 92	     * fleetsave wants caution, and everything else is a routine step the mood leaves alone.
 93	     */
 94	    private function appetiteDirection(AiCandidateActionType $type): int
 95	    {
 96	        return match ($type) {
 97	            AiCandidateActionType::Raid => 1,
 98	            AiCandidateActionType::FleetSave => -1,
 99	            default => 0,
100	        };
101	    }
102	
103	    /** @param array<int, ScoredCandidate> $candidates */
104	    public function select(AiProfile $profile, array $candidates, string $decisionKey): ScoredCandidate
105	    {
106	        $best = $candidates[0];
107	        // Skill affects choice among close options, never whether a clearly
108	        // superior safety or economy decision is eligible to win.
109	        $nearEqual = array_values(array_filter(
110	            $candidates,
111	            static fn (ScoredCandidate $candidate): bool => $candidate->score >= $best->score - $profile->skill_band->selectionMargin(),
112	        ));
113	        $index = (int) floor($this->randomSource->unitInterval($profile->random_seed, $decisionKey . ':select') * count($nearEqual));
114	
115	        return $nearEqual[min($index, count($nearEqual) - 1)];
116	    }
